'use strict';
/* ===== Utilidades ===== */
const $=(s,e=document)=>e.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad=n=>String(n).padStart(2,'0');
const ymd=(d=new Date())=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const D=s=>new Date(s+'T12:00');
const addDays=(s,n)=>{const d=D(s);d.setDate(d.getDate()+n);return ymd(d)};
const diffDays=(a,b)=>Math.round((D(b)-D(a))/864e5);
const fmtD=s=>D(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','');
const fmtL=s=>D(s).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});
const num=v=>{const n=parseFloat(String(v).replace(',','.'));return isFinite(n)?n:null};
const r0=n=>Math.round(n),r1=n=>Math.round(n*10)/10;
const sum=(a,f=x=>x)=>a.reduce((s,x)=>s+(f(x)||0),0);
const days=n=>Array.from({length:n},(_,i)=>addDays(ymd(),-(n-1-i)));
const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
const WD=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'],WDs=WD.map(x=>x.slice(0,3));
const SLOTS=[['cafe','Café da manhã'],['almoco','Almoço'],['lanche','Lanche'],['jantar','Jantar'],['extra','Refeição extra']];
const ACT={sedentario:['Sedentário (pouco ou nenhum exercício)',1.2],leve:['Leve (1–3 dias/semana)',1.375],moderado:['Moderado (3–5 dias/semana)',1.55],intenso:['Intenso (6–7 dias/semana)',1.725]};
const IC={home:'M3 11l9-8 9 8v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',dumb:'M6 6v12M18 6v12M3 9v6M21 9v6M6 12h12',food:'M7 3v8a2 2 0 0 0 2 2v8M11 3v8M7 7h4M17 3c-2 2-3 5-3 8h3v10',drop:'M12 3s6 6.5 6 11a6 6 0 0 1-12 0c0-4.5 6-11 6-11z',chart:'M4 20V4M4 20h16M8 16l4-5 3 3 5-7',more:'M5 12h.01M12 12h.01M19 12h.01',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM4 21a8 8 0 0 1 16 0',scale:'M5 4h14l2 16H3zM9 10a3 3 0 0 1 6 0',plus:'M12 5v14M5 12h14',check:'M5 12l5 5 9-10',trash:'M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13',edit:'M4 20h4L19 9l-4-4L4 16zM14 6l4 4',flag:'M5 21V4M5 4h12l-2 4 2 4H5',copy:'M9 9h11v11H9zM5 15V4h11',swap:'M7 4L3 8l4 4M3 8h14M17 20l4-4-4-4M21 16H7',down:'M12 4v12M6 12l6 6 6-6M5 21h14',bolt:'M13 2L4 14h7l-1 8 9-12h-7z'};
const ico=n=>`<svg class="ic" viewBox="0 0 24 24" aria-hidden="true"><path d="${IC[n]||''}"/></svg>`;
const bar=(p,c='')=>`<div class="bar ${c} ${p>100?'over':''}" role="progressbar" aria-valuenow="${r0(p)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${clamp(p)}%"></i></div>`;
const empty=(i,t,x,b='')=>`<div class="empty">${ico(i)}<b>${t}</b><div>${x}</div>${b?`<p>${b}</p>`:''}</div>`;
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('on'),2400)}
function modal(html){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="sheet" role="dialog" aria-modal="true">${html}</div>`;m.addEventListener('mousedown',e=>{if(e.target===m)m.remove()});document.body.append(m);const f=m.querySelector('input:not([disabled]),select,button');f&&f.focus();return m}
function confirmBox(msg,ok='Confirmar',danger=true){return new Promise(res=>{const m=modal(`<h3>Confirmação</h3><p>${msg}</p><div class="row"><button class="btn ghost" data-n>Cancelar</button><button class="btn ${danger?'danger':''}" data-y>${ok}</button></div>`);m.querySelector('[data-n]').onclick=()=>{m.remove();res(false)};m.querySelector('[data-y]').onclick=()=>{m.remove();res(true)}})}
function fld(f,v){const id='f_'+f.k,val=v??f.def??'';
 if(f.t==='check')return `<label class="chk"><input type="checkbox" name="${f.k}" ${val?'checked':''}> ${esc(f.l)}</label>`;
 let i;
 if(f.t==='select')i=`<select id="${id}" name="${f.k}">${f.o.map(([a,b])=>`<option value="${esc(a)}" ${String(a)===String(val)?'selected':''}>${esc(b)}</option>`).join('')}</select>`;
 else if(f.t==='area')i=`<textarea id="${id}" name="${f.k}" rows="3">${esc(val)}</textarea>`;
 else i=`<input id="${id}" name="${f.k}" type="${f.t==='num'?'text':f.t||'text'}" ${f.t==='num'?'inputmode="decimal"':''} ${f.t==='date'&&f.min?`min="${f.min}"`:''} ${f.t==='date'&&f.max?`max="${f.max}"`:''} value="${esc(val)}" ${f.dis?'disabled':''} autocomplete="off">`;
 return `<div class="fld"><label for="${id}">${esc(f.l)}${f.r?' *':''}</label>${i}${f.h?`<small>${esc(f.h)}</small>`:''}</div>`}
function form(title,fields,vals,onSave,sub='Salvar'){
 const m=modal(`<h3>${esc(title)}</h3><form novalidate>${fields.map(f=>fld(f,vals[f.k])).join('')}<p class="err" role="alert"></p><div class="row"><button type="button" class="btn ghost" data-x>Cancelar</button><button class="btn" type="submit">${sub}</button></div></form>`);
 const fm=m.querySelector('form'),er=m.querySelector('.err');m.querySelector('[data-x]').onclick=()=>m.remove();
 fm.onsubmit=async e=>{e.preventDefault();const o={};const bad=t=>{er.textContent=t};
  for(const f of fields){if(f.dis){o[f.k]=vals[f.k];continue}const el=fm.elements[f.k];let v=f.t==='check'?el.checked:el.value.trim();
   if(f.t==='num'){if(v===''){if(f.r)return bad(`${f.l}: obrigatório`);v=null}else{v=num(v);if(v===null)return bad(`${f.l}: número inválido`);if((f.min!=null&&v<f.min)||(f.max!=null&&v>f.max))return bad(`${f.l}: use um valor entre ${f.min??'0'} e ${f.max??'∞'}`)}}
   else if(f.t==='date'){if(f.r&&!v)return bad(`${f.l}: obrigatório`);if(v&&!/^\d{4}-\d{2}-\d{2}$/.test(v))return bad(`${f.l}: data inválida`);if(v&&f.min&&v<f.min)return bad(`${f.l}: não pode ser antes de ${fmtD(f.min)}`);if(v&&f.max&&v>f.max)return bad(`${f.l}: não pode ser depois de ${fmtD(f.max)}`)}
   else if(f.r&&!v&&f.t!=='check')return bad(`${f.l}: obrigatório`);
   if(typeof v==='string'&&v.length>(f.t==='area'?1000:120))return bad(`${f.l}: texto longo demais`);
   o[f.k]=v}
  try{const r=await onSave(o);if(r)return bad(r)}catch(x){return bad('Erro ao salvar: '+x.message)}
  m.remove();await refresh();toast('Salvo ✓')}}
/* ===== Estado ===== */
const DEF={theme:'dark',waterGoal:2000,waterQuick:[200,300,500],stepGoal:8000,weighInterval:7,kcalAdjust:0,kcalOverride:null,protG:1.6,fatPct:25};
let S={},ui={tdate:ymd(),dwd:new Date().getDay(),range:30,fq:''};
async function load(){const o={};for(const t of db.tables)o[t.name]=await t.toArray();const kv=Object.fromEntries(o.kv.map(r=>[r.key,r]));
 S={...o,tpls:kv.mealTemplates?.items||[],profile:kv.profile||null,settings:{...DEF,...(kv.settings||{})},meta:kv.meta};S.weights.sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0)}
const SEED_W=[
 [2,'Força A','15h–16h','25 min','Força A: agachamento 2x10; flexão apoiada 2x8; elevação de quadril 2x12; prancha 2x15s',[['Agachamento','2x10'],['Flexão apoiada','2x8'],['Elevação de quadril','2x12'],['Prancha','2x15s']]],
 [3,'Caminhada','15h–16h','20–25 min','Caminhada: 5 min confortável + 10–15 min ritmo moderado + 5 min confortável',[['Caminhada','5 min confortável + 10–15 min ritmo moderado + 5 min confortável']]],
 [4,'Recuperação e passeio com o cachorro','Livre','Livre','Recuperação e passeio habitual com o cachorro',[['Passeio habitual com o cachorro','']]],
 [5,'Força B','15h–16h','25 min','Força B: afundo com apoio 2x8 por perna; flexão na parede/apoiada 2x8; superman 2x10; panturrilha 2x15; prancha lateral 2x15s',[['Afundo com apoio','2x8 por perna'],['Flexão na parede/apoiada','2x8'],['Superman','2x10'],['Panturrilha','2x15'],['Prancha lateral','2x15s']]],
 [6,'Caminhada e corda opcional','15h–16h','20–30 min','Caminhada; corda opcional em intervalos curtos, somente se estiver confortável',[['Caminhada',''],['Corda (opcional)','intervalos curtos, somente se estiver confortável']]],
 [0,'Recuperação e passeio com o cachorro','Livre','Livre','Recuperação e passeio habitual com o cachorro',[['Passeio habitual com o cachorro','']]],
 [1,'Descanso e passeio com o cachorro','Livre','Livre','Descanso e passeio habitual com o cachorro',[['Passeio habitual com o cachorro','']]]];
const SEED_H=['Fiz refeições regulares e completas','Bebi água ao longo do dia','Respeitei meu descanso','Passeei com meu cachorro'];
async function seed(){if(S.meta)return;
 for(const [day,name,time,dur,orig,ex] of SEED_W)await db.workouts.add({day,name,time,duration:dur,note:orig,source:'planilha',ex:ex.map(([n,p])=>({name:n,plan:p}))});
 for(const name of SEED_H)await db.habits.add({name,active:true,source:'planilha'});
 await db.kv.put({key:'meta',seeded:1,v:1,at:ymd()});await load()}
async function refresh(){await load();render()}
const setKV=async(k,v)=>{await db.kv.put({...v,key:k})};
/* ===== Regras e cálculos ===== */
const lastW=()=>S.weights[S.weights.length-1];
const nextWeigh=()=>S.weights.length?addDays(lastW().date,S.settings.weighInterval):null;
const curKg=()=>lastW()?.kg??S.profile?.weight??null;
function calc(){const P=S.profile||{},s=S.settings,w=curKg(),miss=[];
 if(!P.age)miss.push('idade');if(!P.height)miss.push('altura');if(!w)miss.push('peso atual');if(!P.sex)miss.push('sexo biológico (a fórmula usa essa informação)');if(!P.activity)miss.push('nível de atividade');
 if(miss.length)return{miss};
 const bmr=10*w+6.25*P.height-5*P.age+(P.sex==='m'?5:-161),f=ACT[P.activity][1],tdee=bmr*f,auto=tdee+(+s.kcalAdjust||0),kcal=s.kcalOverride||auto;
 const p=s.protG*w,fat=kcal*s.fatPct/100/9,c=Math.max(0,(kcal-p*4-fat*9)/4);
 return{bmr,f,tdee,auto,kcal,p,fat,c,w,P,man:!!s.kcalOverride}}
const food=id=>S.foods.find(f=>f.id===id);
const nut=(f,q)=>{const k=q/(f.ref||100);return{kcal:f.kcal*k,p:f.p*k,c:f.c*k,f:f.f*k}};
const tot=a=>({kcal:sum(a,x=>x.kcal),p:sum(a,x=>x.p),c:sum(a,x=>x.c),f:sum(a,x=>x.f)});
const dayLog=d=>S.foodlog.filter(x=>x.date===d);
const dayTot=d=>tot(dayLog(d));
const planEntries=(wd,slot)=>S.plan.filter(x=>x.wd===wd&&(!slot||x.slot===slot)).map(x=>({...x,food:food(x.foodId)})).filter(x=>x.food).map(x=>({...x,...nut(x.food,x.qty)}));
const waterDay=d=>sum(S.water.filter(x=>x.date===d),x=>x.ml);
const stepsDay=d=>S.steps.find(x=>x.date===d)?.steps??null;
const hlog=(d,id)=>S.habitlog.find(x=>x.key===`${d}|${id}`);
const aHabits=()=>S.habits.filter(h=>h.active);
function consist(n=30,id=null){let done=0,reg=0;for(const d of days(n))for(const h of(id?S.habits.filter(x=>x.id===id):aHabits())){const l=hlog(d,h.id);if(l){reg++;if(l.done)done++}}return{done,reg,pct:reg?done/reg*100:null}}
function goalP(g){let st=g.start,cur=g.cur??g.start;
 if(g.kind==='peso'){st=g.start??S.weights[0]?.kg??null;cur=lastW()?.kg??null}
 if(g.kind==='consist'){st=0;cur=consist(30).pct}
 if(st==null||cur==null||g.target==null)return{pct:null,st,cur};
 const pct=g.target===st?(cur===g.target?100:0):(cur-st)/(g.target-st)*100;return{pct:clamp(pct),st,cur}}
const sessFor=(d,wid)=>S.sessions.find(x=>x.date===d&&x.wid===wid);
const wkFor=d=>S.workouts.filter(w=>w.day===D(d).getDay());
function sessProg(d){let done=0,total=0;for(const w of wkFor(d)){const s=sessFor(d,w.id);total+=w.ex.length;if(s)done+=s.items.filter(i=>i.done).length}return{done,total}}
/* ===== Gráficos SVG ===== */
function line(pts,{unit='',target=null}={}){if(!pts.length)return empty('chart','Sem registros no período','Registre dados para ver o gráfico.');
 const W=600,H=190,L=38,R=12,T=14,B=26,xs=pts.map(p=>D(p.x).getTime()),x0=Math.min(...xs),x1=Math.max(...xs),ys=pts.map(p=>p.y).concat(target!=null?[target]:[]);
 let lo=Math.min(...ys),hi=Math.max(...ys);if(lo===hi){lo-=1;hi+=1}const pd=(hi-lo)*.15;lo-=pd;hi+=pd;
 const X=t=>x1===x0?(L+W-R)/2:L+(t-x0)/(x1-x0)*(W-L-R),Y=v=>T+(1-(v-lo)/(hi-lo))*(H-T-B);
 const path=pts.map((p,i)=>`${i?'L':'M'}${X(xs[i]).toFixed(1)} ${Y(p.y).toFixed(1)}`).join(' ');
 return `<svg class="ch" viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de linha, ${pts.length} registros">${[0,.5,1].map(f=>{const v=lo+(hi-lo)*f;return `<line class="gl" x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}"/><text x="2" y="${Y(v)+4}">${r1(v)}</text>`}).join('')}
 ${target!=null?`<line x1="${L}" x2="${W-R}" y1="${Y(target)}" y2="${Y(target)}" stroke="var(--kc)" stroke-dasharray="5 4"/><text x="${W-R-60}" y="${Y(target)-4}" style="fill:var(--kc)">meta ${target}${unit}</text>`:''}
 <path d="${path}" fill="none" stroke="var(--ac)" stroke-width="2.5" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${X(xs[i])}" cy="${Y(p.y)}" r="4" fill="var(--ac)"><title>${fmtD(p.x)}: ${p.y}${unit}</title></circle>`).join('')}
 <text x="${L}" y="${H-6}">${fmtD(pts[0].x)}</text><text x="${W-R}" y="${H-6}" text-anchor="end">${fmtD(pts[pts.length-1].x)}</text></svg>`}
function bars(items,{goal=null,color='var(--ac)',unit=''}={}){const W=600,H=170,L=38,B=22,T=10,mx=Math.max(1,goal||0,...items.map(i=>i.v)),bw=(W-L-8)/items.length,Y=v=>T+(1-v/mx)*(H-T-B);
 if(!items.some(i=>i.v>0))return empty('chart','Sem registros no período','Os dados aparecem aqui conforme você registra.');
 return `<svg class="ch" viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de barras, ${items.length} dias"><line class="gl" x1="${L}" x2="${W-8}" y1="${Y(0)}" y2="${Y(0)}"/><text x="2" y="${Y(mx)+8}">${r0(mx)}</text>
 ${items.map((i,k)=>i.v>0?`<rect x="${L+k*bw+bw*.15}" y="${Y(i.v)}" width="${bw*.7}" height="${Y(0)-Y(i.v)}" rx="3" fill="${color}"><title>${fmtD(i.d)}: ${r0(i.v)}${unit}</title></rect>`:'').join('')}
 ${goal?`<line x1="${L}" x2="${W-8}" y1="${Y(goal)}" y2="${Y(goal)}" stroke="var(--kc)" stroke-dasharray="5 4"/>`:''}
 <text x="${L}" y="${H-5}">${fmtD(items[0].d)}</text><text x="${W-8}" y="${H-5}" text-anchor="end">${fmtD(items[items.length-1].d)}</text></svg>`}
const ring=(p,c,t)=>{const R=40,C=2*Math.PI*R;return `<div class="ring"><svg width="96" height="96" viewBox="0 0 96 96"><circle cx="48" cy="48" r="${R}" fill="none" stroke="var(--s2)" stroke-width="10"/><circle cx="48" cy="48" r="${R}" fill="none" stroke="${c}" stroke-width="10" stroke-linecap="round" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-clamp(p)/100)}" style="transition:stroke-dashoffset .6s"/></svg><div>${t}</div></div>`};
const macroRow=(l,v,g,c)=>`<div style="margin:8px 0"><div class="row sp sm"><span>${l}</span><span>${r0(v)}${g?` / ${r0(g)}`:''} g</span></div>${bar(g?v/g*100:0,c)}</div>`;
/* ===== Navegação ===== */
const PAGES={hoje:['Hoje','home'],treino:['Treino','dumb'],dieta:['Dieta','food'],diario:['Registro','drop'],peso:['Peso','scale'],evolucao:['Evolução','chart'],perfil:['Perfil e metas','user'],mais:['Mais','more']};
const route=()=>(location.hash.replace('#/','')||'hoje').split('?')[0];
function nav(){const r=route(),link=(k,t)=>`<a href="#/${k}" ${(r===k||(k==='mais'&&['peso','evolucao','perfil'].includes(r)))?'aria-current="page"':''}>${ico(PAGES[k][1])}<span>${t||PAGES[k][0]}</span></a>`;
 $('#tabs').innerHTML=['hoje','treino','dieta','diario','mais'].map(k=>link(k)).join('');
 $('#side').innerHTML=`<div class="brand"><i></i>Satori</div>`+['hoje','treino','dieta','diario','peso','evolucao','perfil'].map(k=>link(k)).join('')}
function render(){nav();const r=PAGES[route()]?route():'hoje';
 document.documentElement.dataset.theme=S.settings.theme==='auto'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):S.settings.theme;
 $('#main').innerHTML=(P[r]||P.hoje)();document.title=`${PAGES[r]?.[0]||''} · Satori`}
window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});
const A={},C={};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-a]');if(!el||!A[el.dataset.a])return;try{await A[el.dataset.a](el.dataset,el)}catch(x){console.error(x);toast('Erro: '+x.message)}});
document.addEventListener('change',async e=>{const el=e.target.closest('[data-c]');if(!el||!C[el.dataset.c])return;try{await C[el.dataset.c](el.dataset,el)}catch(x){console.error(x);toast('Erro: '+x.message)}});
const $card=(t,b,x='')=>`<section class="card ${x}"><h2>${t}</h2>${b}</section>`;
const P={};
/* ===== HOJE ===== */
P.hoje=()=>{const t=ymd(),h=new Date().getHours(),g=h<12?'Bom dia':h<18?'Boa tarde':'Boa noite',nm=S.profile?.name,c=calc(),dt=dayTot(t),w=waterDay(t),st=stepsDay(t),sp=sessProg(t),wk=wkFor(t),hb=aHabits(),hd=hb.filter(x=>hlog(t,x.id)?.done).length,nx=nextWeigh(),lw=lastW();
 const goals=S.goals.filter(x=>x.status==='ativa');
 const kcalG=c.kcal;
 return `<h1>${g}${nm?', '+esc(nm):''}</h1><p class="sub">${fmtL(t)}</p>
 ${backupNag()}${!S.profile?`<div class="card hl" style="margin-bottom:14px"><b>Comece pelo seu perfil</b><p class="sub">Com idade, altura, peso e atividade, o app calcula suas estimativas.</p><a class="btn" href="#/perfil">Preencher perfil</a></div>`:''}
 <div class="row" style="margin-bottom:14px">${[['water','Água','drop'],['steps','Passos','bolt'],['food','Consumo','food'],['weight','Peso','scale']].map(([a,l,i])=>`<button class="btn ghost" data-a="q_${a}">${ico(i)}${l}</button>`).join('')}</div>
 <div class="grid g2">
 ${$card('Treino de hoje',wk.length?wk.map(w=>`<div class="li"><div class="grow"><b>${esc(w.name)}</b><div class="sm">${esc(w.time)} · ${esc(w.duration)}</div></div></div>`).join('')+`<div style="margin:10px 0 6px" class="row sp sm"><span>Progresso</span><span>${sp.done}/${sp.total} itens</span></div>${bar(sp.total?sp.done/sp.total*100:0)}<p><a class="btn sm2" href="#/treino" data-a="today">Abrir treino</a></p>`:empty('dumb','Sem treino planejado','Hoje não há treino cadastrado.'),'hl')}
 ${$card('Calorias e macros',c.miss?`<div class="note">Faltam dados para estimar: ${c.miss.join(', ')}. <a href="#/perfil">Completar perfil</a></div><p class="big">${r0(dt.kcal)} <small>kcal consumidas</small></p>`:`<div class="row">${ring(dt.kcal/kcalG*100,'var(--kc)',r0(dt.kcal/kcalG*100)+'%')}<div class="grow"><div class="big">${r0(dt.kcal)}<small> / ${r0(kcalG)} kcal</small></div><small>${dt.kcal>kcalG?`${r0(dt.kcal-kcalG)} acima da meta`:`${r0(kcalG-dt.kcal)} kcal restantes`}</small></div></div>${macroRow('Proteínas',dt.p,c.p,'')}${macroRow('Carboidratos',dt.c,c.c,'')}${macroRow('Gorduras',dt.f,c.fat,'')}`)}
 ${$card('Hidratação',`<div class="big">${w}<small> / ${S.settings.waterGoal} ml</small></div>${bar(w/S.settings.waterGoal*100,'wa')}<div class="row" style="margin-top:12px">${S.settings.waterQuick.map(q=>`<button class="btn ghost sm2" data-a="addWater" data-ml="${q}">+${q} ml</button>`).join('')}</div>`)}
 ${$card('Passos',`<div class="big">${st??'—'}<small> / ${S.settings.stepGoal}</small></div>${bar((st||0)/S.settings.stepGoal*100)}<p class="sm">${st==null?'Não registrado hoje.':''}</p><button class="btn ghost sm2" data-a="q_steps">${st==null?'Registrar':'Atualizar'}</button>`)}
 ${$card('Hábitos',hb.length?`<div class="big">${hd}<small> / ${hb.length} concluídos</small></div>${bar(hb.length?hd/hb.length*100:0)}<p class="sm">${hb.filter(x=>!hlog(t,x.id)).length} ainda não registrados hoje.</p><a class="btn ghost sm2" href="#/diario">Marcar hábitos</a>`:empty('check','Nenhum hábito','Crie hábitos na aba Registro.'))}
 ${$card('Peso',lw?`<div class="big">${lw.kg}<small> kg</small></div><p class="sm">${S.weights.length>1?`Início: ${S.weights[0].kg} kg (${r1(lw.kg-S.weights[0].kg)>0?'+':''}${r1(lw.kg-S.weights[0].kg)} kg)`:'Primeiro registro'}</p><p class="${ymd()<nx?'':'chip ok'}">${ymd()<nx?`Próxima pesagem: ${fmtL(nx)}`:'Pesagem liberada hoje'}</p>`:empty('scale','Sem pesagens','Registre seu peso inicial.','<button class="btn sm2" data-a="q_weight">Registrar peso</button>'))}
 </div>
 <div style="margin-top:14px">${$card('Metas ativas',goals.length?goals.map(goalLine).join(''):empty('flag','Nenhuma meta ativa','Crie metas no seu perfil. Nada é imposto automaticamente.','<a class="btn sm2" href="#/perfil">Criar meta</a>'))}</div>`};
const goalLine=g=>{const p=goalP(g);return `<div class="li"><div class="grow"><div class="row sp"><b>${esc(g.title)}</b><span class="sm">${p.pct==null?'sem dados':r0(p.pct)+'%'}</span></div>${bar(p.pct||0)}<small>${p.cur!=null?`${r1(p.cur)}${esc(g.unit||'')}`:'—'} → ${g.target}${esc(g.unit||'')}${g.deadline?' · até '+fmtD(g.deadline):''}</small></div></div>`};
A.today=()=>{ui.tdate=ymd()};
A.q_water=()=>A.addWaterCustom();A.q_steps=()=>A.editSteps({date:ymd()});A.q_food=()=>A.addLog({});A.q_weight=()=>A.addW();
/* ===== TREINO ===== */
P.treino=()=>{const d=ui.tdate,wd=D(d).getDay(),wk=wkFor(d),t0=addDays(d,-wd);
 const strip=`<div class="strip">${Array.from({length:7},(_,i)=>{const x=addDays(t0,i),sp=sessProg(x);return `<button data-a="tday" data-d="${x}" aria-pressed="${x===d}" aria-label="${fmtL(x)}"><small>${WDs[i]}</small><b>${D(x).getDate()}</b>${sp.done?'<span class="dot"></span>':''}</button>`}).join('')}</div>`;
 return `<div class="row sp"><div><h1>Treino</h1><p class="sub">${fmtL(d)}${d===ymd()?' · hoje':''}</p></div><div class="row"><button class="btn ghost sm2" data-a="${ui.editPlan?'plan_off':'plan_on'}">${ico('edit')}${ui.editPlan?'Concluir edição':'Editar plano'}</button><button class="btn ghost sm2" data-a="newWorkout">${ico('plus')}Novo treino</button></div></div>${strip}
 ${wk.length?wk.map(w=>workoutCard(w,d)).join(''):empty('dumb','Nada planejado para este dia','Adicione um treino para este dia da semana.','<button class="btn sm2" data-a="newWorkout">Novo treino</button>')}
 <div class="grid g2" style="margin-top:14px">${$card('Calendário do mês',calendar(d))}${$card('Histórico de sessões',sessHist())}</div><div style="margin-top:14px">${importCard()}</div>`};
function workoutCard(w,d){const s=sessFor(d,w.id),items=w.ex.map(e=>{const it=s?.items.find(i=>i.name===e.name);return{...e,done:!!it?.done,actual:it?.actual||'',load:it?.load??''}});
 const dn=items.filter(i=>i.done).length;
 return `<section class="card" style="margin-bottom:14px"><div class="row sp"><div><span class="tag">Planejado</span><h2 style="margin:2px 0">${esc(w.name)}</h2><div class="sm">${esc(w.time)} · ${esc(w.duration)}</div></div><span class="chip ${dn===items.length&&items.length?'ok':''}">${dn}/${items.length}</span></div>
 ${w.note?`<div class="note" style="margin:10px 0">Planilha: ${esc(w.note)}</div>`:''}
 ${ui.editPlan?`<div class="row" style="margin-bottom:10px"><button class="btn ghost sm2" data-a="editWorkout" data-id="${w.id}">${ico('edit')}Dados do treino</button><button class="btn ghost sm2" data-a="addEx" data-id="${w.id}">${ico('plus')}Exercício</button><button class="btn danger sm2" data-a="delWorkout" data-id="${w.id}">${ico('trash')}Excluir treino</button></div>`:''}
 ${items.map((e,i)=>`<div class="ex ${e.done?'done':''}"><div class="row"><button class="tick" data-a="tick" data-w="${w.id}" data-n="${esc(e.name)}" aria-pressed="${e.done}" aria-label="Concluído: ${esc(e.name)}">${e.done?ico('check'):''}</button><div class="grow"><b>${esc(e.name)}</b><div class="sm">Planejado: ${esc(e.plan||'conforme planilha')}</div>${e.note?`<div class="sm">${esc(e.note)}</div>`:''}</div>
  ${ui.editPlan?`<button class="ib" data-a="editEx" data-w="${w.id}" data-i="${i}" aria-label="Editar">${ico('edit')}</button><button class="ib" data-a="delEx" data-w="${w.id}" data-i="${i}" aria-label="Excluir">${ico('trash')}</button>`:''}</div>
  <div class="two"><input placeholder="Realizado (ex.: 2x8)" aria-label="Realizado ${esc(e.name)}" value="${esc(e.actual)}" data-c="exf" data-f="actual" data-w="${w.id}" data-n="${esc(e.name)}"><input inputmode="decimal" placeholder="kg" aria-label="Carga ${esc(e.name)}" value="${esc(e.load)}" data-c="exf" data-f="load" data-w="${w.id}" data-n="${esc(e.name)}"></div></div>`).join('')||empty('dumb','Sem exercícios','Edite o plano para adicionar.')}
 <div class="fld"><label>Observações da sessão</label><textarea rows="2" data-c="snote" data-w="${w.id}">${esc(s?.note||'')}</textarea></div></section>`}
async function upSess(wid,date,fn){const w=S.workouts.find(x=>x.id===wid);let s=sessFor(date,wid);
 const base=s?{...s}:{date,wid,wname:w.name,items:[],note:''};
 for(const e of w.ex)if(!base.items.find(i=>i.name===e.name))base.items.push({name:e.name,plan:e.plan,done:false,actual:'',load:''});
 fn(base);await db.sessions.put(base);await refresh()}
A.tday=({d})=>{ui.tdate=d;render()};A.plan_on=()=>{ui.editPlan=true;render()};A.plan_off=()=>{ui.editPlan=false;render()};
A.tick=({w,n})=>upSess(+w,ui.tdate,s=>{const i=s.items.find(x=>x.name===n);i.done=!i.done});
C.exf=({w,n,f},el)=>{let v=el.value.trim().slice(0,80);if(f==='load'){if(v&&(num(v)===null||num(v)<0||num(v)>1000)){toast('Carga inválida');el.value='';v=''}else if(v)v=num(v)}return upSess(+w,ui.tdate,s=>{s.items.find(x=>x.name===n)[f]=v})};
C.snote=({w},el)=>upSess(+w,ui.tdate,s=>{s.note=el.value.trim().slice(0,1000)});
const wfields=[{k:'name',l:'Nome do treino',r:1},{k:'day',l:'Dia da semana',t:'select',o:WD.map((n,i)=>[i,n])},{k:'time',l:'Horário',def:'Livre'},{k:'duration',l:'Duração',def:'25 min'},{k:'note',l:'Observações',t:'area'}];
A.newWorkout=()=>form('Novo treino',wfields,{day:D(ui.tdate).getDay()},async v=>{await db.workouts.add({...v,day:+v.day,ex:[],source:'usuário'})});
A.editWorkout=({id})=>{const w=S.workouts.find(x=>x.id==id);form('Editar treino',wfields,w,async v=>{await db.workouts.put({...w,...v,day:+v.day})})};
A.delWorkout=async({id})=>{const w=S.workouts.find(x=>x.id==id);if(await confirmBox(`Excluir o treino “${esc(w.name)}”? As sessões já registradas continuam no histórico.`,'Excluir')){await db.workouts.delete(w.id);await refresh()}};
const exf=[{k:'name',l:'Exercício',r:1},{k:'plan',l:'Planejado (séries x repetições / tempo)'},{k:'note',l:'Observações'}];
A.addEx=({id})=>{const w=S.workouts.find(x=>x.id==id);form('Novo exercício',exf,{},async v=>{if(w.ex.some(e=>e.name===v.name))return'Já existe exercício com esse nome neste treino';w.ex.push(v);await db.workouts.put(w)})};
A.editEx=({w,i})=>{const W=S.workouts.find(x=>x.id==w);form('Editar exercício',exf,W.ex[i],async v=>{if(W.ex.some((e,k)=>k!=i&&e.name===v.name))return'Nome já usado';W.ex[i]=v;await db.workouts.put(W)})};
A.delEx=async({w,i})=>{const W=S.workouts.find(x=>x.id==w);if(await confirmBox(`Remover “${esc(W.ex[i].name)}” do plano? Registros passados permanecem.`,'Remover')){W.ex.splice(i,1);await db.workouts.put(W);await refresh()}};
function calendar(d){const m0=d.slice(0,8)+'01',f=D(m0).getDay(),n=new Date(D(m0).getFullYear(),D(m0).getMonth()+1,0).getDate();
 let h=`<div class="row sp" style="margin-bottom:8px"><b>${D(m0).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</b><span class="sm">verde = treino concluído</span></div><div class="cal">${WDs.map(x=>`<b>${x[0]}</b>`).join('')}`+'<span class="nu"></span>'.repeat(f);
 for(let i=1;i<=n;i++){const x=m0.slice(0,8)+pad(i),ss=S.sessions.filter(s=>s.date===x),dn=ss.some(s=>s.items.some(i=>i.done)),all=ss.length&&ss.every(s=>s.items.every(i=>i.done));h+=`<span class="${all?'on':dn?'part':''} ${x===ymd()?'td':''}">${i}</span>`}
 return h+'</div>'}
function sessHist(){const ss=[...S.sessions].filter(s=>s.items.some(i=>i.done||i.actual)).sort((a,b)=>a.date<b.date?1:-1).slice(0,12);
 return ss.length?ss.map(s=>`<div class="li"><div class="grow"><b>${esc(s.wname)}</b><div class="sm">${fmtD(s.date)} · ${s.items.filter(i=>i.done).length}/${s.items.length} itens${s.items.some(i=>i.load)?' · '+s.items.filter(i=>i.load).map(i=>esc(i.name)+' '+i.load+'kg').join(', '):''}</div>${s.note?`<div class="sm">“${esc(s.note)}”</div>`:''}</div><button class="ib" data-a="delSess" data-id="${s.id}" aria-label="Excluir sessão">${ico('trash')}</button></div>`).join(''):empty('dumb','Nenhuma sessão ainda','Marque exercícios para criar seu histórico.')}
A.delSess=async({id})=>{if(await confirmBox('Excluir esta sessão do histórico?','Excluir')){await db.sessions.delete(+id);await refresh()}};
/* ===== DIETA ===== */
const foodFields=[{k:'name',l:'Nome do alimento',r:1},{k:'unit',l:'Unidade base',t:'select',o:[['g','gramas (g)'],['ml','mililitros (ml)']]},{k:'ref',l:'Valores nutricionais referentes a quantos g/ml?',t:'num',r:1,min:1,max:10000,def:100,h:'Ex.: 100 (como na tabela nutricional)'},{k:'kcal',l:'Calorias (kcal)',t:'num',r:1,min:0,max:10000},{k:'p',l:'Proteínas (g)',t:'num',r:1,min:0,max:1000},{k:'c',l:'Carboidratos (g)',t:'num',r:1,min:0,max:1000},{k:'f',l:'Gorduras (g)',t:'num',r:1,min:0,max:1000},{k:'portion',l:'Porção personalizada (nome)',h:'Ex.: 1 fatia, 1 colher de sopa'},{k:'portionQty',l:'Quanto vale 1 porção (g/ml)',t:'num',min:0,max:10000}];
const foodOpts=()=>S.foods.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(f=>[f.id,`${f.name} (${f.unit})`]);
P.dieta=()=>{const c=calc(),t=ymd(),wd=ui.dwd,dt=dayTot(t),pe=planEntries(wd),pt=tot(pe),log=dayLog(t);
 const row=e=>`<div class="li"><div class="grow"><b>${esc(e.food.name)}</b><div class="sm">${e.qty} ${e.food.unit} · ${r0(e.kcal)} kcal · P${r0(e.p)} C${r0(e.c)} G${r0(e.f)}</div></div><button class="ib" data-a="editPlan" data-id="${e.id}" aria-label="Editar ou substituir">${ico('swap')}</button><button class="ib" data-a="delPlan" data-id="${e.id}" aria-label="Excluir">${ico('trash')}</button></div>`;
 return `<h1>Dieta</h1><p class="sub">Monte sua própria alimentação. Valores são estimativas, não prescrição.</p>
 <div class="grid g2">${$card('Consumo de hoje vs meta',`<div class="big">${r0(dt.kcal)}<small> / ${c.kcal?r0(c.kcal):'—'} kcal</small></div>${c.kcal?bar(dt.kcal/c.kcal*100,'kc'):'<div class="note">Defina o perfil para ter uma meta.</div>'}${macroRow('Proteínas',dt.p,c.p)}${macroRow('Carboidratos',dt.c,c.c)}${macroRow('Gorduras',dt.f,c.fat)}`)}
 ${$card('Registrado hoje',(log.length?log.map(l=>`<div class="li"><div class="grow"><b>${esc(l.name)}</b><div class="sm">${esc(SLOTS.find(s=>s[0]===l.slot)?.[1]||'')} · ${l.qty} ${l.unit} · ${r0(l.kcal)} kcal</div></div><button class="ib" data-a="delLog" data-id="${l.id}" aria-label="Excluir">${ico('trash')}</button></div>`).join(''):empty('food','Nada registrado hoje','Registre o que comeu ou use “Comi” no plano.'))+`<button class="btn sm2" data-a="addLog">${ico('plus')}Registrar consumo</button>`)}</div>
 <h2 style="margin-top:22px">Plano semanal</h2><div class="strip">${WD.map((n,i)=>`<button data-a="dwd" data-i="${i}" aria-pressed="${i===wd}"><small>${n.slice(0,3)}</small><b>${r0(planEntries(i).reduce((s,e)=>s+e.kcal,0))||'–'}</b></button>`).join('')}</div>
 <div class="card" style="margin-bottom:14px"><div class="row sp"><div><b>${WD[wd]}</b><div class="sm">${r0(pt.kcal)} kcal · P${r0(pt.p)} C${r0(pt.c)} G${r0(pt.f)}${c.kcal?` · meta ${r0(c.kcal)}`:''}</div></div><button class="btn ghost sm2" data-a="copyDay">${ico('copy')}Copiar dia</button></div></div>
 ${!S.foods.length?$card('Alimentos',empty('food','Cadastre seus alimentos primeiro','Informe calorias e macros conforme a embalagem ou tabela.','<button class="btn sm2" data-a="addFood">Cadastrar alimento</button>')):''}
 ${SLOTS.map(([k,l])=>{const es=planEntries(wd,k);return `<section class="card" style="margin-bottom:12px"><div class="row sp"><h2 style="margin:0">${l}</h2><div class="row"><span class="sm">${r0(sum(es,e=>e.kcal))} kcal</span>${es.length?`<button class="btn ghost sm2" data-a="eatMeal" data-k="${k}" title="Registrar como consumido hoje">Comi</button><button class="ib" data-a="copyMeal" data-k="${k}" aria-label="Copiar refeição">${ico('copy')}</button>`:''}<button class="ib" data-a="addPlan" data-k="${k}" aria-label="Adicionar alimento">${ico('plus')}</button></div></div>${es.map(row).join('')||'<p class="sm">Vazio.</p>'}<div class="row" style="margin-top:8px">${es.length?`<button class="btn ghost sm2" data-a="saveTpl" data-k="${k}">Salvar como modelo</button>`:''}${S.tpls.length?`<button class="btn ghost sm2" data-a="useTpl" data-k="${k}">Inserir modelo</button>`:''}</div></section>`}).join('')}
 ${$card('Histórico alimentar (14 dias)',(()=>{const r=days(14).reverse().map(d=>({d,t:dayTot(d)})).filter(x=>x.t.kcal>0);return r.length?`<table><tr><th>Dia</th><th>kcal</th><th>P</th><th>C</th><th>G</th>${c.kcal?'<th>vs meta</th>':''}</tr>${r.map(x=>`<tr><td>${fmtD(x.d)}</td><td>${r0(x.t.kcal)}</td><td>${r0(x.t.p)}</td><td>${r0(x.t.c)}</td><td>${r0(x.t.f)}</td>${c.kcal?`<td>${x.t.kcal>c.kcal?'+':''}${r0(x.t.kcal-c.kcal)}</td>`:''}</tr>`).join('')}</table>`:empty('chart','Sem histórico','O consumo registrado aparece aqui.')})())}
 <div style="margin-top:14px">${$card('Refeições modelo',tplList())}</div><div style="margin-top:14px">${$card('Meus alimentos',`<div class="row" style="margin-bottom:10px"><input style="flex:1" type="search" placeholder="Buscar alimento" aria-label="Buscar alimento" value="${esc(ui.fq)}" data-c="fq"><button class="btn sm2" data-a="addFood">${ico('plus')}Novo</button></div>${S.foods.filter(f=>f.name.toLowerCase().includes(ui.fq.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name)).map(f=>`<div class="li"><div class="grow"><b>${esc(f.name)}</b><div class="sm">por ${f.ref} ${f.unit}: ${f.kcal} kcal · P${f.p} C${f.c} G${f.f}${f.portion?` · 1 ${esc(f.portion)} = ${f.portionQty} ${f.unit}`:''} · fonte: ${esc(f.source||'manual')}</div></div><button class="ib" data-a="editFood" data-id="${f.id}" aria-label="Editar">${ico('edit')}</button><button class="ib" data-a="delFood" data-id="${f.id}" aria-label="Excluir">${ico('trash')}</button></div>`).join('')||'<p class="sm">Nenhum alimento.</p>'}<p class="note">Base preparada para importar tabelas como a TACO (campos <code>source</code> e <code>externalId</code>), respeitando fonte e licença. Nesta versão o cadastro é manual.</p>`)}</div>`};
A.dwd=({i})=>{ui.dwd=+i;render()};C.fq=(_,el)=>{ui.fq=el.value;render();const i=$('input[type=search]');i.focus();i.setSelectionRange(99,99)};
A.addFood=()=>form('Novo alimento',foodFields,{},async v=>{await db.foods.add({...v,source:'manual',externalId:null})});
A.editFood=({id})=>{const f=food(+id);form('Editar alimento',foodFields,f,async v=>{await db.foods.put({...f,...v});});};
A.delFood=async({id})=>{const f=food(+id),u=S.plan.filter(p=>p.foodId===f.id).length;if(await confirmBox(`Excluir “${esc(f.name)}”?${u?` Ele será removido de ${u} item(ns) do plano.`:''} O histórico de consumo já registrado é mantido.`,'Excluir')){for(const p of S.plan.filter(p=>p.foodId===f.id))await db.plan.delete(p.id);await db.foods.delete(f.id);await refresh()}};
function entryFields(){return[{k:'foodId',l:'Alimento',t:'select',o:foodOpts()},{k:'qty',l:'Quantidade (g/ml)',t:'num',min:0.1,max:10000,h:'Ou use porções abaixo'},{k:'por',l:'Número de porções (opcional)',t:'num',min:0.1,max:100,h:'Usa a porção definida no alimento'}]}
function entryQty(v){const f=food(+v.foodId);if(!f)return[null,'Cadastre um alimento antes'];let q=v.qty;if(!q&&v.por){if(!f.portionQty)return[null,'Este alimento não tem porção definida'];q=v.por*f.portionQty}return q?[q]:[null,'Informe a quantidade ou as porções']}
A.addPlan=({k})=>{if(!S.foods.length)return toast('Cadastre um alimento primeiro');form(`Adicionar — ${SLOTS.find(s=>s[0]===k)[1]}`,entryFields(),{},async v=>{const[q,e]=entryQty(v);if(e)return e;await db.plan.add({wd:ui.dwd,slot:k,foodId:+v.foodId,qty:q})})};
A.editPlan=({id})=>{const p=S.plan.find(x=>x.id==id);form('Editar / substituir alimento',[entryFields()[0],{k:'qty',l:'Quantidade (g/ml)',t:'num',r:1,min:0.1,max:10000}],p,async v=>{await db.plan.put({...p,foodId:+v.foodId,qty:v.qty})})};
A.delPlan=async({id})=>{if(await confirmBox('Remover este alimento do plano?','Remover')){await db.plan.delete(+id);await refresh()}};
const dayOpts=ex=>[['all','Todos os outros dias'],...WD.map((n,i)=>[i,n]).filter(([i])=>i!==ex)];
A.copyDay=()=>form(`Copiar ${WD[ui.dwd]} para…`,[{k:'to',l:'Dia de destino',t:'select',o:dayOpts(ui.dwd)},{k:'rep',l:'Substituir o que já existe no destino',t:'check',def:true}],{},async v=>{const src=S.plan.filter(p=>p.wd===ui.dwd),tg=v.to==='all'?[0,1,2,3,4,5,6].filter(i=>i!==ui.dwd):[+v.to];for(const t of tg){if(v.rep)for(const p of S.plan.filter(p=>p.wd===t))await db.plan.delete(p.id);for(const p of src)await db.plan.add({wd:t,slot:p.slot,foodId:p.foodId,qty:p.qty})}});
A.copyMeal=({k})=>form('Copiar refeição para…',[{k:'to',l:'Dia de destino',t:'select',o:dayOpts(-1)}],{to:ui.dwd===6?0:ui.dwd+1},async v=>{const src=S.plan.filter(p=>p.wd===ui.dwd&&p.slot===k),tg=v.to==='all'?[0,1,2,3,4,5,6].filter(i=>i!==ui.dwd):[+v.to];for(const t of tg)for(const p of src)await db.plan.add({wd:t,slot:k,foodId:p.foodId,qty:p.qty})});
A.eatMeal=async({k})=>{const es=planEntries(ui.dwd,k);for(const e of es)await db.foodlog.add({date:ymd(),slot:k,foodId:e.foodId,name:e.food.name,qty:e.qty,unit:e.food.unit,kcal:e.kcal,p:e.p,c:e.c,f:e.f});await refresh();toast('Refeição registrada hoje ✓')};
A.addLog=()=>{if(!S.foods.length)return toast('Cadastre um alimento primeiro');form('Registrar consumo',[{k:'date',l:'Data',t:'date',r:1,def:ymd(),max:ymd()},{k:'slot',l:'Refeição',t:'select',o:SLOTS},...entryFields()],{},async v=>{const[q,e]=entryQty(v);if(e)return e;const f=food(+v.foodId),n=nut(f,q);await db.foodlog.add({date:v.date,slot:v.slot,foodId:f.id,name:f.name,qty:q,unit:f.unit,...n})})};
A.delLog=async({id})=>{if(await confirmBox('Excluir este registro de consumo?','Excluir')){await db.foodlog.delete(+id);await refresh()}};
/* ===== REGISTRO: água, passos, hábitos ===== */
P.diario=()=>{const t=ymd(),s=S.settings,w=S.water.filter(x=>x.date===t).sort((a,b)=>a.id-b.id),st=S.steps.slice().sort((a,b)=>a.date<b.date?1:-1).slice(0,10),hb=aHabits(),ds=days(7),c30=consist(30);
 return `<h1>Registro diário</h1><p class="sub">Água, passos e hábitos. Dias sem registro aparecem como “não registrado”, nunca como falha.</p><div class="grid g2">
 ${$card('Água hoje',`<div class="big">${waterDay(t)}<small> / ${s.waterGoal} ml</small></div>${bar(waterDay(t)/s.waterGoal*100,'wa')}<div class="row" style="margin:12px 0">${s.waterQuick.map(q=>`<button class="btn ghost sm2" data-a="addWater" data-ml="${q}">+${q}</button>`).join('')}<button class="btn ghost sm2" data-a="addWaterCustom">Outra</button></div>
  ${w.map(x=>`<div class="li"><div class="grow">${x.ml} ml <span class="sm">${esc(x.time||'')}</span></div><button class="ib" data-a="editWater" data-id="${x.id}" aria-label="Editar">${ico('edit')}</button><button class="ib" data-a="delWater" data-id="${x.id}" aria-label="Excluir">${ico('trash')}</button></div>`).join('')||'<p class="sm">Nada registrado hoje.</p>'}
  <p class="sm" style="margin-top:10px">Últimos 7 dias: ${ds.map(d=>`${fmtD(d)} ${waterDay(d)||'–'}`).reverse().slice(0,7).join(' · ')}</p><button class="btn ghost sm2" data-a="waterCfg">Configurar meta e botões</button>`)}
 ${$card('Passos',`<div class="big">${stepsDay(t)??'—'}<small> / ${s.stepGoal}</small></div>${bar((stepsDay(t)||0)/s.stepGoal*100)}<div class="row" style="margin:12px 0"><button class="btn sm2" data-a="editSteps" data-date="${t}">${stepsDay(t)==null?'Registrar hoje':'Corrigir hoje'}</button><button class="btn ghost sm2" data-a="editSteps">Outro dia</button><button class="btn ghost sm2" data-a="stepCfg">Meta</button></div>${st.map(x=>`<div class="li"><div class="grow">${fmtD(x.date)} · <b>${x.steps}</b> ${x.steps>=s.stepGoal?'<span class="chip ok">meta ✓</span>':''}</div><button class="ib" data-a="editSteps" data-date="${x.date}" aria-label="Editar">${ico('edit')}</button><button class="ib" data-a="delSteps" data-date="${x.date}" aria-label="Excluir">${ico('trash')}</button></div>`).join('')||'<p class="sm">Sem registros de passos.</p>'}`)}</div>
 <div style="margin-top:14px">${$card('Hábitos',(hb.length?`<div class="sm" style="margin-bottom:10px">Toque para alternar: <b>vazio</b> = não registrado → ✓ feito → ✕ não feito. Consistência 30 dias: ${c30.pct==null?'sem registros':`${r0(c30.pct)}% (${c30.done} de ${c30.reg} registrados)`}</div><div style="overflow-x:auto"><div class="hg" style="min-width:420px"><span></span>${ds.map(d=>`<span class="h">${WDs[D(d).getDay()]}<br>${D(d).getDate()}</span>`).join('')}
  ${hb.map(h=>`<div><b>${esc(h.name)}</b><div class="sm">${(()=>{const x=consist(30,h.id);return x.pct==null?'sem registros':r0(x.pct)+'% · '+x.reg+' registrados'})()}</div></div>${ds.map(d=>{const l=hlog(d,h.id);return `<button class="hc" data-a="hab" data-h="${h.id}" data-d="${d}" data-s="${l?(l.done?1:0):''}" aria-label="${esc(h.name)} em ${fmtD(d)}: ${l?(l.done?'feito':'não feito'):'não registrado'}">${l?(l.done?'✓':'✕'):''}</button>`}).join('')}`).join('')}</div></div>`:empty('check','Nenhum hábito','Crie um hábito para acompanhar.'))+`<div class="row" style="margin-top:12px"><button class="btn sm2" data-a="addHabit">${ico('plus')}Novo hábito</button>${S.habits.length?'<button class="btn ghost sm2" data-a="manageHabits">Gerenciar</button>':''}</div>`)}</div>`};
const nowT=()=>new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
A.addWater=async({ml})=>{await db.water.add({date:ymd(),ml:+ml,time:nowT()});await refresh();toast(`+${ml} ml ✓`)};
A.addWaterCustom=()=>form('Registrar água',[{k:'ml',l:'Quantidade (ml)',t:'num',r:1,min:1,max:5000}],{},async v=>{await db.water.add({date:ymd(),ml:v.ml,time:nowT()})});
A.editWater=({id})=>{const x=S.water.find(w=>w.id==id);form('Editar registro de água',[{k:'ml',l:'Quantidade (ml)',t:'num',r:1,min:1,max:5000}],x,async v=>{await db.water.put({...x,ml:v.ml})})};
A.delWater=async({id})=>{if(await confirmBox('Excluir este registro de água?','Excluir')){await db.water.delete(+id);await refresh()}};
A.waterCfg=()=>form('Água: meta e botões rápidos',[{k:'g',l:'Meta diária (ml)',t:'num',r:1,min:200,max:10000},{k:'q',l:'Botões rápidos (ml, separados por vírgula)',r:1,h:'Ex.: 200, 300, 500'}],{g:S.settings.waterGoal,q:S.settings.waterQuick.join(', ')},async v=>{const q=v.q.split(',').map(num);if(!q.length||q.length>6||q.some(x=>x===null||x<=0||x>5000))return'Use até 6 números entre 1 e 5000';await setKV('settings',{...S.settings,waterGoal:v.g,waterQuick:q})});
A.stepCfg=()=>form('Meta diária de passos',[{k:'g',l:'Passos por dia',t:'num',r:1,min:100,max:100000}],{g:S.settings.stepGoal},async v=>{await setKV('settings',{...S.settings,stepGoal:Math.round(v.g)})});
A.editSteps=({date})=>{const cur=date?stepsDay(date):null;form('Passos',[{k:'date',l:'Data',t:'date',r:1,max:ymd(),def:date||ymd()},{k:'steps',l:'Passos',t:'num',r:1,min:0,max:200000}],{date:date||ymd(),steps:cur},async v=>{await db.steps.put({date:v.date,steps:Math.round(v.steps)})})};
A.delSteps=async({date})=>{if(await confirmBox(`Excluir passos de ${fmtD(date)}?`,'Excluir')){await db.steps.delete(date);await refresh()}};
A.hab=async({h,d,s})=>{const key=`${d}|${h}`;if(s==='')await db.habitlog.put({key,date:d,habitId:+h,done:true});else if(s==='1')await db.habitlog.put({key,date:d,habitId:+h,done:false});else await db.habitlog.delete(key);await refresh()};
A.addHabit=()=>form('Novo hábito',[{k:'name',l:'Nome do hábito',r:1}],{},async v=>{if(S.habits.some(h=>h.name.toLowerCase()===v.name.toLowerCase()&&h.active))return'Já existe um hábito com esse nome';await db.habits.add({name:v.name,active:true,source:'usuário'})});
A.manageHabits=()=>{const m=modal(`<h3>Gerenciar hábitos</h3><p class="sm">Arquivar esconde o hábito, mas preserva todo o histórico.</p>${S.habits.map(h=>`<div class="li"><div class="grow ${h.active?'':'mu'}">${esc(h.name)} ${h.active?'':'(arquivado)'}</div><button class="btn ghost sm2" data-r="${h.id}">Renomear</button><button class="btn ghost sm2" data-t="${h.id}">${h.active?'Arquivar':'Reativar'}</button></div>`).join('')}<p><button class="btn ghost" data-x>Fechar</button></p>`);
 m.querySelector('[data-x]').onclick=()=>m.remove();m.querySelectorAll('[data-t]').forEach(b=>b.onclick=async()=>{const h=S.habits.find(x=>x.id==b.dataset.t);await db.habits.put({...h,active:!h.active});m.remove();await refresh()});
 m.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{m.remove();const h=S.habits.find(x=>x.id==b.dataset.r);form('Renomear hábito',[{k:'name',l:'Nome',r:1}],h,async v=>{await db.habits.put({...h,name:v.name})})})};
/* ===== PESO ===== */
P.peso=()=>{const w=S.weights,iv=S.settings.weighInterval,nx=nextWeigh(),t=ymd(),ok=!nx||t>=nx,g=S.goals.find(x=>x.kind==='peso'&&x.status==='ativa'),lw=lastW();
 return `<div class="row sp"><div><h1>Peso</h1><p class="sub">Uma pesagem a cada ${iv} dias ou mais, para reduzir ruído do dia a dia.</p></div><button class="btn" data-a="addW" ${ok?'':'style="opacity:.55" title="Pesagem ainda não liberada"'}>${ico('plus')}Registrar</button></div>
 <div class="card ${ok?'hl':''}" style="margin-bottom:14px">${!w.length?'<b>Registre seu peso inicial</b><p class="sub">O primeiro registro pode ser feito a qualquer momento.</p>':ok?`<b>Pesagem liberada</b><p class="sub">Você já pode registrar um novo peso (liberado desde ${fmtL(nx)}).</p>`:`<b>Próxima pesagem: ${fmtL(nx)}</b><p class="sub">Faltam ${diffDays(t,nx)} dia(s). Última pesagem em ${fmtD(lw.date)}.</p>`}<button class="btn ghost sm2" data-a="wInterval">Alterar intervalo (mín. 7 dias)</button></div>
 <div class="grid g3" style="margin-bottom:14px">${[['Inicial',w[0]?.kg],['Atual',lw?.kg],['Meta',g?.target]].map(([l,v])=>`<div class="card"><span class="tag">${l}</span><div class="big">${v!=null?v:'—'}<small> kg</small></div></div>`).join('')}</div>
 ${$card('Evolução',line(w.map(x=>({x:x.date,y:x.kg})),{unit:' kg',target:g?.target}))}
 <div style="margin-top:14px">${$card('Histórico e comparação',w.length?`<table><tr><th>Data</th><th>Peso</th><th>vs anterior</th><th>vs início</th><th></th></tr>${w.map((x,i)=>{const dv=i?r1(x.kg-w[i-1].kg):null,di=i?r1(x.kg-w[0].kg):null,f=n=>n==null?'—':(n>0?'+':'')+n;return `<tr><td>${fmtD(x.date)}</td><td><b>${x.kg}</b></td><td>${f(dv)}</td><td>${f(di)}</td><td style="text-align:right"><button class="ib" data-a="editW" data-id="${x.id}" aria-label="Editar">${ico('edit')}</button><button class="ib" data-a="delW" data-id="${x.id}" aria-label="Excluir">${ico('trash')}</button></td></tr>`}).reverse().join('')}</table>`:empty('scale','Sem pesagens','Registre seu primeiro peso.','<button class="btn sm2" data-a="addW">Registrar peso</button>'))}</div>`};
A.addW=()=>{const nx=nextWeigh(),t=ymd();if(nx&&t<nx)return toast(`Bloqueado: próxima pesagem em ${fmtD(nx)}`);form('Registrar peso',[{k:'date',l:'Data',t:'date',r:1,min:nx||undefined,max:t,def:t},{k:'kg',l:'Peso (kg)',t:'num',r:1,min:20,max:400},{k:'note',l:'Observação',t:'area'}],{},async v=>{if(nx&&v.date<nx)return`Data mínima permitida: ${fmtD(nx)}`;await db.weights.add(v)})};
A.editW=({id})=>{const x=S.weights.find(w=>w.id==id),i=S.weights.indexOf(x),pv=S.weights[i-1],nx=S.weights[i+1],iv=S.settings.weighInterval;
 form('Corrigir pesagem',[{k:'date',l:'Data',t:'date',r:1,max:ymd()},{k:'kg',l:'Peso (kg)',t:'num',r:1,min:20,max:400},{k:'note',l:'Observação',t:'area'}],x,async v=>{if(v.date!==x.date){if(pv&&diffDays(pv.date,v.date)<iv)return`Precisa ser ${iv}+ dias após a pesagem anterior (${fmtD(pv.date)})`;if(nx&&diffDays(v.date,nx.date)<iv)return`Precisa ser ${iv}+ dias antes da próxima pesagem (${fmtD(nx.date)})`}await db.weights.put({...x,...v})})};
A.delW=async({id})=>{if(await confirmBox('Excluir esta pesagem? Isso não pode ser desfeito (faça backup antes se quiser).','Excluir')){await db.weights.delete(+id);await refresh()}};
A.wInterval=()=>form('Intervalo entre pesagens',[{k:'d',l:'Dias',t:'num',r:1,min:7,max:90,h:'Mínimo permitido: 7 dias'}],{d:S.settings.weighInterval},async v=>{await setKV('settings',{...S.settings,weighInterval:Math.round(v.d)})});
/* ===== EVOLUÇÃO ===== */
P.evolucao=()=>{const n=ui.range,from=n?addDays(ymd(),-n+1):'0000-00-00',n2=Math.min(n||30,30),s=S.settings,c=calc();
 const w=S.weights.filter(x=>x.date>=from).map(x=>({x:x.date,y:x.kg})),ds=days(n2),g=S.weights.length?S.goals.find(x=>x.kind==='peso'&&x.status==='ativa'):null;
 const wk=S.sessions.filter(x=>x.date>=from&&x.items.some(i=>i.done)).length,hs=aHabits().map(h=>({h,...consist(n||365,h.id)}));
 return `<div class="row sp"><div><h1>Evolução</h1><p class="sub">Tudo vem dos seus registros reais.</p></div><select aria-label="Período" style="width:auto" data-c="range">${[[7,'7 dias'],[30,'30 dias'],[90,'90 dias'],[365,'1 ano'],[0,'Tudo']].map(([v,l])=>`<option value="${v}" ${v===n?'selected':''}>${l}</option>`).join('')}</select></div>
 <div class="grid g2">${$card('Peso (kg)',line(w,{unit:' kg',target:g?.target}))}${$card('Calorias consumidas',bars(ds.map(d=>({d,v:dayTot(d).kcal})),{goal:c.kcal,color:'var(--kc)',unit:' kcal'})+`<p class="sm">Últimos ${n2} dias${c.kcal?'; linha = meta':''}.</p>`)}
 ${$card('Água (ml)',bars(ds.map(d=>({d,v:waterDay(d)})),{goal:s.waterGoal,color:'var(--wa)',unit:' ml'}))}${$card('Passos',bars(ds.map(d=>({d,v:stepsDay(d)||0})),{goal:s.stepGoal,unit:' passos'}))}
 ${$card('Treinos',`<div class="big">${wk}<small> sessões com exercícios concluídos</small></div><p class="sm">no período selecionado</p>${sessHist()}`)}
 ${$card('Hábitos',hs.length?hs.map(x=>`<div class="li"><div class="grow"><div class="row sp"><span>${esc(x.h.name)}</span><span class="sm">${x.pct==null?'não registrado':r0(x.pct)+'%'}</span></div>${bar(x.pct||0)}<small>${x.reg} dia(s) registrados · ${x.done} feitos${x.reg<(n||365)?' · dias sem registro não contam como falha':''}</small></div></div>`).join(''):empty('check','Sem hábitos','Crie hábitos na aba Registro.'))}
 ${$card('Metas',S.goals.length?S.goals.map(g=>goalLine(g)+`<div class="li"><span class="chip ${g.status==='ativa'?'ac':''}">${g.status}</span>${(g.history||[]).length?`<small>${g.history.length} atualizações</small>`:''}</div>`).join(''):empty('flag','Sem metas','Crie metas no perfil.'))}</div>`};
C.range=({},el)=>{ui.range=+el.value;render()};
/* ===== PERFIL, METAS, CÁLCULOS, BACKUP ===== */
const pf=[{k:'name',l:'Nome',r:1},{k:'age',l:'Idade',t:'num',r:1,min:10,max:110},{k:'height',l:'Altura (cm)',t:'num',r:1,min:100,max:250},{k:'weight',l:'Peso atual (kg)',t:'num',r:1,min:20,max:400},{k:'sex',l:'Sexo biológico (opcional)',t:'select',o:[['','Prefiro não informar'],['f','Feminino'],['m','Masculino']],h:'Usado só na fórmula de metabolismo basal'},{k:'activity',l:'Nível de atividade física',t:'select',o:Object.entries(ACT).map(([k,v])=>[k,v[0]])},{k:'experience',l:'Experiência com exercícios',t:'select',o:[['iniciante','Iniciante'],['intermediario','Intermediário'],['avancado','Avançado']]},{k:'freq',l:'Frequência de treino (dias/semana)',t:'num',min:0,max:7},{k:'limits',l:'Restrições físicas e limitações',t:'area'},{k:'allergies',l:'Alergias',t:'area'},{k:'prefs',l:'Preferências alimentares',t:'area'}];
P.perfil=()=>{const p=S.profile,c=calc(),s=S.settings;
 return `<h1>Perfil e metas</h1><p class="sub">Tudo editável. Atualizar o perfil não apaga seus históricos.</p><div class="grid g2">
 ${$card('Perfil',p?`<table>${[['Nome',p.name],['Idade',p.age+' anos'],['Altura',p.height+' cm'],['Peso atual',curKg()+' kg'],['Sexo biológico',p.sex==='m'?'Masculino':p.sex==='f'?'Feminino':'Não informado'],['Atividade',ACT[p.activity]?.[0]||'—'],['Experiência',p.experience||'—'],['Treinos/semana',p.freq??'—'],['Limitações',p.limits||'—'],['Alergias',p.allergies||'—'],['Preferências',p.prefs||'—']].map(([a,b])=>`<tr><th>${a}</th><td>${esc(b)}</td></tr>`).join('')}</table><p><button class="btn sm2" data-a="editProfile">${ico('edit')}Editar</button></p>`:empty('user','Cadastre seu perfil','Seus dados ficam apenas neste aparelho.','<button class="btn sm2" data-a="editProfile">Criar perfil</button>'))}
 ${$card('Calorias e metabolismo (estimativas)',(c.miss?`<div class="note">Não dá para calcular ainda. Falta: <b>${c.miss.join(', ')}</b>.</div>`:`<div class="grid g3"><div><span class="tag">TMB</span><div class="big">${r0(c.bmr)}</div></div><div><span class="tag">Gasto diário</span><div class="big">${r0(c.tdee)}</div></div><div><span class="tag">Meta${c.man?' (manual)':''}</span><div class="big">${r0(c.kcal)}</div></div></div>${macroRow('Proteínas',c.p,0)}${macroRow('Carboidratos',c.c,0)}${macroRow('Gorduras',c.fat,0)}
  <details class="note" style="margin-top:10px"><summary>Como foi calculado</summary><p><b>TMB</b> (Mifflin-St Jeor, 1990): 10×peso(kg) + 6,25×altura(cm) − 5×idade ${c.P.sex==='m'?'+ 5':'− 161'} = <b>${r0(c.bmr)}</b> kcal.</p><p><b>Gasto diário</b> = TMB × fator de atividade (${c.f}) = <b>${r0(c.tdee)}</b> kcal.</p><p><b>Meta</b> = gasto ${s.kcalAdjust>=0?'+':'−'} ajuste (${Math.abs(s.kcalAdjust)} kcal)${c.man?`; substituída pelo valor manual de ${s.kcalOverride} kcal`:''}.</p><p><b>Proteína</b> = ${s.protG} g/kg × ${c.w} kg. <b>Gordura</b> = ${s.fatPct}% das kcal ÷ 9. <b>Carboidratos</b> = kcal restantes ÷ 4.</p></details>`)+`<p class="note">São estimativas populacionais, não prescrição médica ou nutricional. Consulte um profissional de saúde.</p><button class="btn ghost sm2" data-a="calcCfg">Ajustes manuais</button>`)}</div>
 <div style="margin-top:14px">${$card('Metas',S.goals.length?S.goals.map(g=>`${goalLine(g)}<div class="row" style="margin-bottom:8px"><span class="chip">${g.status}</span>${g.kind==='manual'?`<button class="btn ghost sm2" data-a="goalUp" data-id="${g.id}">Atualizar progresso</button>`:''}<button class="btn ghost sm2" data-a="goalSt" data-id="${g.id}">${g.status==='pausada'?'Retomar':'Pausar'}</button><button class="ib" data-a="editGoal" data-id="${g.id}" aria-label="Editar">${ico('edit')}</button><button class="ib" data-a="delGoal" data-id="${g.id}" aria-label="Excluir">${ico('trash')}</button></div>`).join('')+'<button class="btn sm2" data-a="addGoal">'+ico('plus')+'Nova meta</button>':empty('flag','Nenhuma meta','Crie as metas que fazem sentido para você — nada é imposto.','<button class="btn sm2" data-a="addGoal">Nova meta</button>'))}</div>
 <div class="grid g2" style="margin-top:14px">${$card('Aparência',`<div class="fld"><label for="th">Tema</label><select id="th" data-c="theme">${[['dark','Preto (padrão)'],['light','Claro'],['auto','Automático']].map(([v,l])=>`<option value="${v}" ${s.theme===v?'selected':''}>${l}</option>`).join('')}</select></div>`)}
 ${$card('Backup e dados',`<p class="sm">Seus dados ficam só neste aparelho (IndexedDB). Limpar dados do navegador, desinstalar o app ou trocar de aparelho os apaga — faça backup com frequência e guarde o arquivo em local seguro.</p><div class="row"><button class="btn sm2" data-a="export">${ico('down')}Exportar backup</button>${canShare()?`<button class="btn ghost sm2" data-a="shareBackup">Compartilhar</button>`:''}<label class="btn ghost sm2" style="cursor:pointer">Restaurar<input type="file" accept=".json,application/json" hidden data-c="import"></label><button class="btn danger sm2" data-a="wipe">Apagar tudo</button></div><p class="sm">${S.meta?.lastBackup?'Último backup: '+fmtD(S.meta.lastBackup):'Nenhum backup feito ainda.'}</p><p class="sm" id="storinfo"></p><p class="sm">Motor: ${esc(window.DB_ENGINE)}</p>`)}</div>
 <div style="margin-top:14px" class="note"><b>Privacidade:</b> nenhum dado é enviado a servidores. O app não usa contas, rastreadores nem APIs externas. Cada aparelho tem seu próprio armazenamento; use backup/restauração para transferir.</div>`};
A.editProfile=()=>{const p=S.profile||{},hasW=S.weights.length>0,fs=pf.map(f=>f.k==='weight'?{...f,dis:hasW,h:hasW?'Registre novas pesagens na aba Peso (preserva o histórico).':'Será salvo como primeira pesagem.',r:!hasW}:f);
 form('Meu perfil',fs,{...p,weight:curKg()},async v=>{const o={...v,key:'profile'};if(!hasW&&v.weight){await db.weights.add({date:ymd(),kg:v.weight,note:'Peso inicial (perfil)'})}delete o.weight;await db.profileLog.add({at:new Date().toISOString(),...o});await db.kv.put(o)})};
