/* Backup */
const REQ={kv:['key'],profileLog:[],goals:['title','target'],weights:['date','kg'],foods:['name','kcal'],plan:['wd','foodId','qty'],foodlog:['date','kcal'],workouts:['name','ex'],sessions:['date','items'],water:['date','ml'],steps:['date','steps'],habits:['name'],habitlog:['key','done']};
function validate(j){if(!j||typeof j!=='object'||j.app!=='saude-e-treino')throw Error('Arquivo não é um backup do Satori');if(typeof j.schema!=='number'||j.schema>1)throw Error('Versão de backup não suportada');if(!j.tables||typeof j.tables!=='object')throw Error('Backup sem tabelas');
 for(const [t,rq] of Object.entries(REQ)){const a=j.tables[t];if(a===undefined)continue;if(!Array.isArray(a))throw Error(`Tabela ${t} inválida`);if(a.length>200000)throw Error(`Tabela ${t} grande demais`);
  for(const r of a){if(!r||typeof r!=='object'||Array.isArray(r))throw Error(`Registro inválido em ${t}`);for(const k of rq)if(!(k in r))throw Error(`Registro de ${t} sem o campo “${k}”`);
   if('date'in r&&!/^\d{4}-\d{2}-\d{2}$/.test(r.date))throw Error(`Data inválida em ${t}`);
   for(const k of['kg','kcal','ml','steps','qty'])if(k in r&&(typeof r[k]!=='number'||!isFinite(r[k])||r[k]<0))throw Error(`Valor inválido “${k}” em ${t}`)}}
 for(const t of Object.keys(j.tables))if(!(t in REQ))throw Error(`Tabela desconhecida: ${t}`)}
async function backupBlob(){const tables={};for(const t of db.tables)tables[t.name]=await t.toArray();return new Blob([JSON.stringify({app:'saude-e-treino',schema:1,exportedAt:new Date().toISOString(),tables},null,1)],{type:'application/json'})}
const markBackup=async()=>{const m=(await db.kv.get('meta'))||{key:'meta'};await db.kv.put({...m,key:'meta',lastBackup:ymd()})};
A.export=async()=>{const blob=await backupBlob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`satori-backup-${ymd()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000);await markBackup();await refresh();toast('Backup exportado ✓')};
A.shareBackup=async()=>{const f=new File([await backupBlob()],`satori-backup-${ymd()}.json`,{type:'application/json'});try{await navigator.share({files:[f],title:'Backup Satori'});await markBackup();await refresh()}catch(e){if(e.name!=='AbortError')toast('Compartilhamento indisponível')}};
const canShare=()=>{try{return !!navigator.canShare&&navigator.canShare({files:[new File(['{}'],'a.json',{type:'application/json'})]})}catch{return false}};
function backupNag(){const has=S.weights.length+S.sessions.length+S.foodlog.length+S.water.length+S.steps.length+S.habitlog.length>0;if(!has)return'';const lb=S.meta?.lastBackup,d=diffDays(lb||S.meta?.at||ymd(),ymd());if(lb?d<14:d<3)return'';return `<div class="card" style="margin-bottom:14px;border-color:var(--ac)"><b>Faça um backup</b><p class="sub">${lb?`Último backup há ${d} dias.`:'Você ainda não fez backup.'} Seus dados só existem neste aparelho.</p><button class="btn sm2" data-a="export">${ico('down')}Exportar agora</button></div>`}
C.import=async({},el)=>{const f=el.files[0];el.value='';if(!f)return;try{if(f.size>25e6)throw Error('Arquivo grande demais');let j;try{j=JSON.parse(await f.text())}catch{throw Error('Arquivo não é um JSON válido')}validate(j);
 const n=Object.values(j.tables).reduce((s,a)=>s+a.length,0);if(!await confirmBox(`Restaurar backup de ${esc(j.exportedAt?.slice(0,10)||'data desconhecida')} com ${n} registros? <b>Isto substitui todos os dados atuais</b> deste aparelho.`,'Substituir tudo'))return;
 await db.transaction('rw',db.tables,async()=>{for(const t of db.tables){await t.clear();if(j.tables[t.name]?.length)await t.bulkAdd(j.tables[t.name])}});await syncPrep();await markBackup();await refresh();toast('Backup restaurado ✓')}catch(e){modal(`<h3>Backup recusado</h3><p class="err">${esc(e.message)}</p><p class="sm">Nada foi alterado.</p><button class="btn" onclick="this.closest('.modal').remove()">Ok</button>`)}};
A.wipe=async()=>{if(!await confirmBox('Apagar <b>todos</b> os dados deste aparelho? Considere exportar um backup antes.','Continuar'))return;form('Confirmar exclusão total',[{k:'t',l:'Digite APAGAR para confirmar',r:1}],{},async v=>{if(v.t!=='APAGAR')return'Digite exatamente APAGAR';for(const t of db.tables)await t.clear()},'Apagar tudo')};
P.mais=()=>`<h1>Mais</h1><div class="grid">${['peso','evolucao','perfil'].map(k=>`<a class="card row" style="text-decoration:none;color:inherit;min-height:64px" href="#/${k}">${ico(PAGES[k][1])}<b>${PAGES[k][0]}</b></a>`).join('')}</div>`;
/* ===== Importar treino por planilha (.xlsx / .csv) ===== */
const nz=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const DAYMAP={dom:0,domingo:0,seg:1,segunda:1,ter:2,terca:2,qua:3,quarta:3,qui:4,quinta:4,sex:5,sexta:5,sab:6,sabado:6};
const dayOf=s=>{const k=nz(s).replace(/-feira$/,'');return k in DAYMAP?DAYMAP[k]:null};
function parseCSV(t){t=t.replace(/^\uFEFF/,'');const f=t.split(/\r?\n/)[0]||'',cm=(f.match(/,/g)||[]).length,sm=(f.match(/;/g)||[]).length,del=sm>cm?';':(!cm&&f.includes('\t')?'\t':',');const rows=[];let r=[],c='',q=false;
 for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch==='"'){if(t[i+1]==='"'){c+='"';i++}else q=false}else c+=ch}else if(ch==='"')q=true;else if(ch===del){r.push(c);c=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&t[i+1]==='\n')i++;r.push(c);rows.push(r);r=[];c=''}else c+=ch}
 if(c||r.length){r.push(c);rows.push(r)}return rows}
async function inflateRaw(u8){const ds=new DecompressionStream('deflate-raw'),w=ds.writable.getWriter();w.write(u8);w.close();return new Uint8Array(await new Response(ds.readable).arrayBuffer())}
async function unzip(buf){const u=new Uint8Array(buf),dv=new DataView(buf);let e=-1;for(let i=u.length-22;i>=Math.max(0,u.length-70000);i--)if(dv.getUint32(i,true)===0x06054b50){e=i;break}
 if(e<0)throw Error('Não é um arquivo .xlsx válido');const n=dv.getUint16(e+10,true);let p=dv.getUint32(e+16,true);const files={};
 for(let k=0;k<n;k++){if(dv.getUint32(p,true)!==0x02014b50)throw Error('Arquivo .xlsx corrompido');const nl=dv.getUint16(p+28,true),el=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true);files[new TextDecoder().decode(u.subarray(p+46,p+46+nl))]={m:dv.getUint16(p+10,true),c:dv.getUint32(p+20,true),s:dv.getUint32(p+24,true),o:dv.getUint32(p+42,true)};p+=46+nl+el+cl}
 return{names:Object.keys(files),async read(name){const f=files[name];if(!f)return null;if(f.s>15e6)throw Error('Arquivo grande demais');const nl=dv.getUint16(f.o+26,true),el=dv.getUint16(f.o+28,true),d=u.subarray(f.o+30+nl+el,f.o+30+nl+el+f.c);return new TextDecoder().decode(f.m===0?d:await inflateRaw(d))}}}
async function parseXLSX(buf){const z=await unzip(buf),X=s=>new DOMParser().parseFromString(s,'application/xml'),ss=[];const sst=await z.read('xl/sharedStrings.xml');
 if(sst)for(const si of X(sst).getElementsByTagName('si'))ss.push([...si.getElementsByTagName('t')].map(t=>t.textContent).join(''));
 const sheets=z.names.filter(n=>/^xl\/worksheets\/sheet\d+\.xml$/.test(n)).sort((a,b)=>parseInt(a.match(/\d+/))-parseInt(b.match(/\d+/))),out=[];
 for(const sn of sheets){const rows=[];for(const row of X(await z.read(sn)).getElementsByTagName('row')){const r=[];for(const c of row.getElementsByTagName('c')){const ref=c.getAttribute('r')||'',col=[...ref.replace(/\d+/g,'')].reduce((a,ch)=>a*26+ch.charCodeAt(0)-64,0)-1,t=c.getAttribute('t'),v=c.getElementsByTagName('v')[0]?.textContent;
   r[col]=t==='s'?ss[+v]:t==='inlineStr'?[...c.getElementsByTagName('t')].map(x=>x.textContent).join(''):(v??'')}
  rows[(+row.getAttribute('r')||rows.length+1)-1]=r}out.push(rows)}return out}
const HCOL=h=>{h=nz(h);return h.startsWith('dia')?'dia':h.startsWith('treino')||h.startsWith('nome')?'treino':h.startsWith('hor')?'hora':h.startsWith('dura')?'dur':h.startsWith('exerc')?'ex':/^(series|prescri|repet)/.test(h)?'plan':h.startsWith('obs')?'obs':null};
function parseRows(rows){const hi=rows.findIndex(r=>r&&r.map(HCOL).includes('dia')&&r.map(HCOL).includes('treino'));if(hi<0)return null;const idx={};rows[hi].forEach((h,i)=>{const k=HCOL(h);if(k&&!(k in idx))idx[k]=i});
 const errors=[],map=new Map();let n=0;
 for(let i=hi+1;i<rows.length;i++){const r=rows[i]||[],g=k=>String(r[idx[k]]??'').trim();if(!r.some(x=>String(x??'').trim()))continue;const d0=g('dia');if(d0.startsWith('#'))continue;
  if(++n>500){errors.push('Mais de 500 linhas: divida a planilha');break}const L=i+1,day=dayOf(d0),name=g('treino');
  if(day===null){errors.push(`Linha ${L}: dia inválido “${d0.slice(0,20)}” (use Segunda a Domingo)`);continue}
  if(!name){errors.push(`Linha ${L}: nome do treino vazio`);continue}
  if([name,g('ex'),g('plan'),g('obs'),g('hora'),g('dur')].some(x=>x.length>200)){errors.push(`Linha ${L}: texto longo demais (máx. 200 caracteres)`);continue}
  const key=day+'|'+nz(name);if(!map.has(key))map.set(key,{day,name,time:g('hora')||'Livre',duration:g('dur')||'Livre',note:'',source:'importado',ex:[]});
  const w=map.get(key),en=g('ex');if(en){if(w.ex.some(e=>nz(e.name)===nz(en)))errors.push(`Linha ${L}: exercício “${en}” repetido em ${name}`);else w.ex.push({name:en,plan:g('plan'),note:g('obs')})}}
 if(!map.size&&!errors.length)errors.push('Nenhum treino encontrado (linhas com # são ignoradas)');return{workouts:[...map.values()],errors}}
C.impW=async({},el)=>{const f=el.files[0];el.value='';if(!f)return;let res;try{if(f.size>5e6)throw Error('Arquivo grande demais (máx. 5 MB)');const ext=f.name.split('.').pop().toLowerCase();
  if(ext==='csv')res=parseRows(parseCSV(await f.text()));else if(ext==='xlsx'){for(const rows of await parseXLSX(await f.arrayBuffer())){res=parseRows(rows);if(res)break}}else throw Error('Use um arquivo .xlsx ou .csv');
  if(!res)throw Error('Não encontrei o cabeçalho (colunas Dia, Treino, Exercício…). Use a planilha modelo.')}catch(e){return modal(`<h3>Importação recusada</h3><p class="err">${esc(e.message)}</p><p class="sm">Nada foi alterado.</p><button class="btn" onclick="this.closest('.modal').remove()">Ok</button>`)}
 if(res.errors.length)return modal(`<h3>Corrija a planilha</h3><p class="sm">${res.errors.length} problema(s). Nada foi alterado.</p>${res.errors.slice(0,12).map(e=>`<p class="err" style="min-height:0">${esc(e)}</p>`).join('')}<button class="btn" onclick="this.closest('.modal').remove()">Ok</button>`);
 const W=res.workouts,m=modal(`<h3>Pré-visualização</h3><p class="sm">${W.length} treino(s), ${sum(W,w=>w.ex.length)} exercício(s):</p><div style="max-height:34vh;overflow:auto">${W.sort((a,b)=>a.day-b.day).map(w=>`<div class="li"><div class="grow"><b>${WD[w.day]} · ${esc(w.name)}</b><div class="sm">${w.ex.map(e=>esc(e.name)+(e.plan?' '+esc(e.plan):'')).join(', ')||'sem exercícios'}</div></div></div>`).join('')}</div>
  <div class="fld" style="margin-top:12px"><label for="imode">Como importar</label><select id="imode"><option value="add">Adicionar aos treinos existentes</option><option value="replace">Substituir todo o plano atual</option></select><small>Sessões já registradas nunca são apagadas.</small></div><div class="row"><button class="btn ghost" data-x>Cancelar</button><button class="btn" data-ok>Importar</button></div>`);
 m.querySelector('[data-x]').onclick=()=>m.remove();m.querySelector('[data-ok]').onclick=async()=>{const rep=m.querySelector('#imode').value==='replace';if(rep&&!await confirmBox('Substituir TODO o plano de treino atual pelo da planilha? (O histórico de sessões é mantido.)','Substituir'))return;
  if(rep)for(const w of S.workouts)await db.workouts.delete(w.id);for(const w of W)await db.workouts.add(w);m.remove();await refresh();toast(`${W.length} treino(s) importado(s) ✓`)}};
const PROMPT_COLS='Dia, Treino, Horário, Duração, Exercício, Séries x repetições, Observações';
function buildPrompt(inc){const p=S.profile||{};const mine=inc&&S.profile?'\n\nMEUS DADOS (já informados no app — não precisa perguntar de novo, mas confirme se algo parecer desatualizado):\n'+[p.age&&`- Idade: ${p.age} anos`,p.height&&`- Altura: ${p.height} cm`,curKg()&&`- Peso atual: ${curKg()} kg`,p.sex&&`- Sexo biológico: ${p.sex==='m'?'masculino':'feminino'}`,p.activity&&`- Nível de atividade: ${ACT[p.activity]?.[0]}`,p.experience&&`- Experiência com exercícios: ${p.experience}`,p.freq!=null&&`- Frequência de treino atual: ${p.freq} dias/semana`,p.limits&&`- Restrições/limitações: ${p.limits}`].filter(Boolean).join('\n'):'';
 return ['Você é um personal trainer experiente, cuidadoso e didático. Vou usar você para criar um plano de treino 100% personalizado para o meu aplicativo Satori. Anexei a planilha modelo do app (ou, se não conseguir ler o anexo, use as colunas descritas abaixo).','','ETAPA 1 — ENTREVISTA','Antes de montar qualquer coisa, me entreviste. Faça no máximo 4 perguntas por mensagem, espere minhas respostas e aprofunde se algo ficar vago. Cubra:','1. Meu objetivo principal (perder gordura, ganhar massa, força, condicionamento, saúde geral…), prazo e o que “sucesso” significa para mim.','2. Minha experiência com treino, o que já funcionou ou não, e como me sinto com cada tipo de exercício.','3. Quantos dias por semana posso treinar, em quais dias e horários, e quanto tempo por sessão.','4. Onde treino (casa, academia, parque) e que equipamentos tenho (peso do corpo, halteres, elásticos, corda, barra, banco…).','5. Lesões, dores, cirurgias, condições de saúde e limitações de movimento.','6. Exercícios que gosto, que odeio ou que não posso fazer; se prefiro treinos curtos e intensos ou longos e tranquilos.','7. Caminhadas, cardio e atividade do dia a dia (trabalho sentado, passeios, esportes).','8. Sono, rotina, energia ao longo da semana e dias de descanso desejados.','9. Como quero progredir (mais repetições, mais carga, mais séries) e se quero semanas mais leves.','','ETAPA 2 — CONFIRMAÇÃO','Resuma o que entendeu e proponha a estrutura (divisão semanal e lógica de progressão). Só avance depois que eu aprovar ou pedir ajustes.','','ETAPA 3 — PLANILHA','Gere o plano exatamente no formato da planilha modelo, com as colunas: '+PROMPT_COLS+'.','Regras do formato:','- Uma linha por exercício; linhas com o mesmo Dia + Treino formam um único treino.','- Dia: apenas Segunda, Terça, Quarta, Quinta, Sexta, Sábado ou Domingo.','- Horário e Duração: texto curto (ex.: 18h, 40 min). Se não souber, deixe vazio.','- Séries x repetições: texto simples (ex.: 3x10, 3x8 por perna, 30s, 20 min).','- Observações: dicas curtas de execução e de progressão por semana.','- Dias de descanso ativo (caminhada, passeio) podem ter uma linha com o exercício correspondente.','- Não invente cargas em kg; use faixas de esforço (ex.: “termine com 2 repetições sobrando”) a menos que eu informe cargas.','- Não escreva cabeçalhos extras, comentários nem linhas em branco dentro da planilha.','','FORMATO DE ENTREGA','Se você consegue criar arquivos, entregue um .xlsx baseado na planilha modelo anexada. Se não, responda com UM único bloco de código CSV (separado por vírgula, com aspas nos campos que tiverem vírgula; primeira linha = cabeçalho exato: '+PROMPT_COLS+'), que eu salvarei como .csv.','','SEGURANÇA','Isto não substitui avaliação médica nem de um profissional de educação física. Se eu citar dor, lesão ou condição de saúde, adapte os exercícios com cautela e recomende que eu consulte um profissional. Priorize técnica e consistência antes de intensidade.',mine,'','Pode começar a entrevista agora com as primeiras perguntas.'].join('\n')}
function importCard(){return $card('Importar treino por planilha',`<p class="sm">Baixe a planilha modelo, preencha (ou peça para uma IA preencher) e importe aqui. Aceita <b>.xlsx</b> e <b>.csv</b>. Nada sai do seu aparelho: a leitura é local.</p><div class="row" style="margin:10px 0"><a class="btn ghost" href="templates/satori-modelo-treino.xlsx" download>${ico('down')}Baixar planilha modelo</a><label class="btn" style="cursor:pointer">${ico('plus')}Importar planilha<input type="file" accept=".xlsx,.csv,text/csv" hidden data-c="impW"></label></div><p class="sm">Prefere CSV? <a href="templates/satori-modelo-treino.csv" download style="color:var(--ac)">baixar modelo .csv</a></p>
 <h3 style="margin-top:18px">Prompt para o ChatGPT</h3><ol class="sm" style="padding-left:18px;margin:0 0 10px"><li>Baixe a planilha modelo acima.</li><li>Copie o prompt, abra o ChatGPT e anexe a planilha modelo.</li><li>Responda a entrevista; ao final ele entrega o .xlsx ou um CSV.</li><li>Importe o arquivo aqui (se vier CSV, salve como .csv).</li></ol>
 <label class="chk"><input type="checkbox" data-c="pInc" ${ui.pInc?'checked':''} ${S.profile?'':'disabled'}> Incluir meus dados do perfil no prompt${S.profile?'':' (preencha o perfil primeiro)'}</label><small class="sm">Os dados só vão ao ChatGPT se você colar o prompt lá. Seu nome não é incluído.</small>
 <textarea id="promptBox" readonly rows="9" aria-label="Prompt para o ChatGPT" style="margin-top:8px;font:.8rem/1.4 ui-monospace,monospace">${esc(buildPrompt(ui.pInc))}</textarea><div class="row" style="margin-top:10px"><button class="btn" data-a="copyPrompt">Copiar prompt</button></div>`)}
C.pInc=({},el)=>{ui.pInc=el.checked;render()};
A.copyPrompt=async()=>{const t=$('#promptBox');try{await navigator.clipboard.writeText(t.value)}catch{t.select();document.execCommand('copy')}toast('Prompt copiado ✓')};
A.reload=()=>location.reload();
/* ===== Refeições modelo (guardadas em kv, sem mudar o esquema do banco) ===== */
const saveTpls=a=>db.kv.put({key:'mealTemplates',items:a});
function tplList(){return S.tpls.length?S.tpls.map(t=>`<div class="li"><div class="grow"><b>${esc(t.name)}</b><div class="sm">${t.items.map(i=>esc(food(i.foodId)?.name||'(alimento removido)')+' '+i.qty+(food(i.foodId)?.unit||'')).join(', ')}</div></div><button class="ib" data-a="delTpl" data-id="${t.id}" aria-label="Excluir modelo">${ico('trash')}</button></div>`).join(''):empty('copy','Nenhum modelo','Monte uma refeição no plano e use “Salvar como modelo” para reutilizar com um toque.')}
A.saveTpl=({k})=>{const es=planEntries(ui.dwd,k);form('Salvar refeição como modelo',[{k:'name',l:'Nome do modelo',r:1,h:'Ex.: Meu café padrão'}],{name:''},async v=>{if(S.tpls.some(t=>nz(t.name)===nz(v.name)))return'Já existe um modelo com esse nome';await saveTpls([...S.tpls,{id:Date.now(),name:v.name,items:es.map(e=>({foodId:e.foodId,qty:e.qty}))}])})};
A.useTpl=({k})=>form(`Inserir modelo — ${SLOTS.find(s=>s[0]===k)[1]}`,[{k:'id',l:'Modelo',t:'select',o:S.tpls.map(t=>[t.id,t.name])}],{},async v=>{const t=S.tpls.find(x=>x.id==v.id);let skip=0;for(const i of t.items){if(!food(i.foodId)){skip++;continue}await db.plan.add({wd:ui.dwd,slot:k,foodId:i.foodId,qty:i.qty})}if(skip)toast(`${skip} alimento(s) do modelo não existem mais`)});
A.delTpl=async({id})=>{if(await confirmBox('Excluir este modelo? Refeições já inseridas no plano não mudam.','Excluir')){await saveTpls(S.tpls.filter(t=>t.id!=id));await refresh()}};
/* ===== Início ===== */
(async()=>{try{await syncPrep();await load();await seed();await syncPrep();await load();render();
 if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});
 if(navigator.storage?.estimate){const e=await navigator.storage.estimate();const el=$('#storinfo');if(el)el.textContent=`Armazenamento usado: ${(e.usage/1024).toFixed(0)} KB`}
 if('serviceWorker'in navigator&&location.protocol!=='file:'){const had=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(had&&!$('#upd')){const u=document.createElement('div');u.id='upd';u.className='card';u.innerHTML='<b>Nova versão do Satori instalada</b><div class="row" style="margin-top:8px"><button class="btn sm2" data-a="reload">Recarregar</button><button class="btn ghost sm2" onclick="this.closest(\'#upd\').remove()">Depois</button></div>';document.body.append(u)}});navigator.serviceWorker.register('sw.js').then(r=>document.addEventListener('visibilitychange',()=>{if(!document.hidden)r.update().catch(()=>{})})).catch(()=>{})}
}catch(e){document.body.innerHTML=`<main><h1>Não foi possível abrir o armazenamento local</h1><p>${esc(e.message)}</p><p>Verifique se o navegador permite IndexedDB (não use aba anônima).</p></main>`}})();
window.__app={get S(){return S}};
